{
  "graph_update": {
    "triple_operations": [
      {
        "type": "insert",
        "graph": {
          "@context": {
            "rdf": "http://www.w3.org/1999/02/22-rdf-syntax-ns#",
            "rdfs": "http://www.w3.org/2000/01/rdf-schema#",
            "owl": "http://www.w3.org/2002/07/owl#",
            "xsd": "http://www.w3.org/2001/XMLSchema#",
            "schema": "http://schema.org/",
            "cd": "https://growgraph.dev/facts/",
            "life": "https://growgraph.dev/ontologies/lifecycle#"
          },
          "@graph": [
            {
              "@id": "life:CompetingInterestDeclaration",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Competing interest declaration",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A documented statement asserting the presence or absence of competing financial or other interests relevant to a work (for example, a publication).",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "schema:CreativeWork"
              }
            },
            {
              "@id": "life:CompetingInterestStatus",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Competing interest status",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A qualitative classification of whether relevant competing interests exist for a given work. Designed as an open class whose concrete states are modelled as subclasses (e.g. no competing interest, competing interest present).",
                "@language": "en"
              }
            },
            {
              "@id": "life:NoCompetingInterest",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "No competing interest",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A competing-interest status denoting that no competing financial or other interests are declared.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "life:CompetingInterestStatus"
              }
            },
            {
              "@id": "life:HasCompetingInterest",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Has competing interest",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A competing-interest status denoting that one or more competing financial or other interests are declared.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "life:CompetingInterestStatus"
              }
            },
            {
              "@id": "life:statesCompetingInterestStatus",
              "@type": [
                "owl:ObjectProperty",
                "owl:FunctionalProperty"
              ],
              "rdfs:label": {
                "@value": "states competing interest status",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Links a competing-interest declaration to a competing-interest status classification (for example life:NoCompetingInterest or life:HasCompetingInterest). Declared functional because a single declaration node should carry one stated status.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "life:CompetingInterestDeclaration"
              },
              "rdfs:range": {
                "@id": "life:CompetingInterestStatus"
              }
            },
            {
              "@id": "life:declaredBy",
              "@type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "declared by",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Identifies the agent (authoring person or organization) responsible for the competing-interest declaration.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "life:CompetingInterestDeclaration"
              },
              "rdfs:range": {
                "@id": "schema:Person"
              },
              "rdfs:subPropertyOf": {
                "@id": "schema:creator"
              }
            },
            {
              "@id": "life:hasDeclarationText",
              "@type": [
                "owl:DatatypeProperty",
                "owl:FunctionalProperty"
              ],
              "rdfs:label": {
                "@value": "has declaration text",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "The textual content of a competing-interest declaration as presented in the source (for example the sentence \"The authors declare no competing financial interest.\"). Declared functional to represent a single canonical declaration text per declaration node.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "life:CompetingInterestDeclaration"
              },
              "rdfs:range": {
                "@id": "xsd:string"
              },
              "rdfs:subPropertyOf": {
                "@id": "schema:description"
              }
            }
          ]
        }
      ]
    }
  }
}

