{
  "graph_update": {
    "triple_operations": [
      {
        "type": "insert",
        "graph": {
          "@context": {
            "rdf": "http://www.w3.org/1999/02/22-rdf-syntax-ns#",
            "rdfs": "http://www.w3.org/2000/01/rdf-schema#",
            "owl": "http://www.w3.org/2002/07/owl#",
            "xsd": "http://www.w3.org/2001/XMLSchema#",
            "schema": "http://schema.org/",
            "cd": "https://growgraph.dev/facts/",
            "matsci": "https://growgraph.dev/ontologies/matsci#",
            "obs": "https://growgraph.dev/ontologies/observation#",
            "life": "https://growgraph.dev/ontologies/lifecycle#",
            "qudt": "http://qudt.org/schema/qudt/",
            "quantitykind": "http://qudt.org/vocab/quantitykind/",
            "perovmat": "https://growgraph.dev/ontologies/perovskitemat#"
          },
          "@graph": [
            {
              "@id": "matsci:PhotoluminescenceRedShift",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Photoluminescence red shift",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A physical phenomenon in which the photoluminescence (PL) emission of a sample is shifted to longer wavelength (lower photon energy) relative to a stated reference (e.g. colloidal NCs in dilute solution). Mechanisms include photon-propagation-mediated self-absorption and re-emission, loss of quantum confinement in larger crystallites, and emission from luminescent impurities or aggregates.",
                "@language": "en"
              },
              "rdfs:subClassOf": [
                {
                  "@id": "obs:PhysicalPhenomenon"
                },
                {
                  "@id": "matsci:PhotonPropagationEffect"
                }
              ]
            },
            {
              "@id": "matsci:SpectralBroadeningProperty",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "spectral broadening",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "An observable material property describing an increase in emission spectral linewidth (for example PL full-width at half-maximum) relative to a reference measurement. Used to record broadened emission attributed to heterogeneity, aggregation, reabsorption/re-emission, or loss of confinement.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "matsci:ObservableMaterialProperty"
              }
            },
            {
              "@id": "matsci:SurfaceBrightSpotFeature",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Surface bright spot feature",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A localized surface morphology feature on a superlattice sample that appears as a bright, submicrometer object in optical maps or microscopy (rhombic or rectangular shapes, sharp edges). May correspond to coalesced nanocrystals, submicrometer crystallites, or luminescent impurity particles residing on the SL surface.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "matsci:SuperlatticeMorphologyState"
              }
            },
            {
              "@id": "matsci:hasBrightSpotCount",
              "@type": [
                "owl:DatatypeProperty",
                "owl:FunctionalProperty"
              ],
              "rdfs:label": {
                "@value": "has bright spot count",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Cardinal count of bright surface spots observed on a superlattice morphology state. Records a single canonical non-negative integer count for a given morphology description.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "matsci:SuperlatticeMorphologyState"
              },
              "rdfs:range": {
                "@id": "xsd:nonNegativeInteger"
              }
            },
            {
              "@id": "matsci:brightSpotInducesRedShift",
              "@type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "bright spot induces red shift",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Relates a superlattice morphology (or its surface bright-spot feature) to an observed photoluminescence red-shift phenomenon, encoding an empirical association such as increased spot count or coverage correlating with larger PL red shift.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "matsci:SuperlatticeMorphologyState"
              },
              "rdfs:range": {
                "@id": "matsci:PhotoluminescenceRedShift"
              }
            },
            {
              "@id": "matsci:photonPropagationContribution",
              "@type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "photon propagation contribution",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Links a photon-propagation effect (self-absorption plus re-emission by material with matching bandgap) to a photoluminescence red-shift outcome, indicating that photon propagation is a contributing mechanism for the observed red shift.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "matsci:PhotonPropagationEffect"
              },
              "rdfs:range": {
                "@id": "matsci:PhotoluminescenceRedShift"
              }
            },
            {
              "@id": "matsci:LossOfQuantumConfinement",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Loss of quantum confinement",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A physical phenomenon in which nanoscale quantum confinement is reduced or lost (for example via coalescence or growth into submicrometer crystals), producing bulk-like optical bandgap behavior and a red-shifted PL compared to confined nanocrystals.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "obs:PhysicalPhenomenon"
              }
            },
            {
              "@id": "matsci:lossOfQuantumConfinementCausesRedShift",
              "@type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "loss of quantum confinement causes red shift",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Relates a LossOfQuantumConfinement phenomenon to a PhotoluminescenceRedShift outcome, capturing the causal interpretation that reduced confinement (e.g. formation of larger crystallites) can produce red-shifted PL.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "matsci:LossOfQuantumConfinement"
              },
              "rdfs:range": {
                "@id": "matsci:PhotoluminescenceRedShift"
              },
              "rdfs:subPropertyOf": {
                "@id": "matsci:associatedWithPhenomenon"
              }
            }
          ]
        }
      ]
    }
  }
}

