              },
              "rdfs:comment": {
                "@value": "An explanatory factor or phenomenon that contributes to an observed photoluminescence red shift in a sample or ensemble (for example interparticle electronic coupling, impurity-derived emission, or photon-propagation effects such as self-absorption).",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "obs:Phenomenon"
              }
            },
            {
