              },
              "rdfs:comment": {
                "@value": "Links a photon-propagation effect (self-absorption, reabsorption, or scattering-mediated spectral bias) to a qudt:QuantityValue representing the magnitude of PL red shift contributed by photon propagation. Domain is matsci:PhotonPropagationEffect.",
