                "@id": "matsciunits:millielectronvolt"
              }
            },
            {
              "@id": "matsci:TransferableAssembly",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Transferable assembly",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "An assembly structure produced at an interface (for example on a liquid) that is suitable for transfer onto a different substrate material (for example silicon or glass) without destructive processing. Represents the transferability quality of an AssemblyStructure.",
