              },
              "rdfs:comment": {
                "@value": "Relates an AssemblyStructure to a target substrate material type to which the assembly can be transferred. Range is matsci:Material so domain ontologies may assert specific substrate classes (for example silicon or glass).",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "matsci:AssemblyStructure"
              },
              "rdfs:range": {
                "@id": "matsci:Material"
              }
            }
