            "obs": "https://growgraph.dev/ontologies/observation#"
          },
          "@graph": [
            {
              "@id": "matsci:PhotoluminescenceRedShift",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Photoluminescence red shift",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A physical phenomenon in which the photoluminescence (PL) emission spectrum of a sample is shifted to longer wavelengths (lower energy). May arise from multiple mechanisms including photon-propagation-mediated self-absorption/re-emission, reduced quantum confinement in larger crystallites, or the presence of luminescent impurities or aggregates.",
                "@language": "en"
              },
              "rdfs:subClassOf": [
                "obs:PhysicalPhenomenon",
                "matsci:PhotonPropagationEffect"
              ]
            },
            {
              "@id": "matsci:SpectralBroadeningProperty",
              "@type": "matsci:ObservableMaterialProperty",
              "rdfs:label": {
                "@value": "spectral broadening",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "An observable material property describing an increase in the spectral linewidth (for example PL full-width at half-maximum). Used to represent broadened emission spectra relative to a reference (e.g. colloidal NC solution).",
                "@language": "en"
              },
              "rdfs:subClassOf": "matsci:ObservableMaterialProperty"
            },
            {
              "@id": "matsci:SurfaceBrightSpotFeature",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Surface bright spot feature",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A localized surface morphology feature of a superlattice (SL) appearing as a bright, submicrometer object in optical maps and microscopy (e.g. rhombic/rectangular objects). May correspond to crystallites, degraded/coalesced nanocrystals, or luminescent impurity particles on the SL surface.",
                "@language": "en"
              },
              "rdfs:subClassOf": "matsci:SuperlatticeMorphologyState"
            },
            {
              "@id": "matsci:hasBrightSpotCount",
              "rdf:type": [
                "owl:DatatypeProperty",
                "owl:FunctionalProperty"
              ],
              "rdfs:label": {
                "@value": "has bright spot count",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Cardinal count of bright surface spots observed on a superlattice sample (non-negative integer). Use on a SuperlatticeMorphologyState to record how many localized bright objects are present; functional because a single morphology state carries at most one canonical reported count.",
                "@language": "en"
              },
              "rdfs:domain": "matsci:SuperlatticeMorphologyState",
              "rdfs:range": "xsd:nonNegativeInteger"
            },
            {
              "@id": "matsci:brightSpotInducesRedShift",
              "rdf:type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "bright spot induces red shift",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Relates a superlattice morphology (or its surface bright-spot feature) to an observed photoluminescence red-shift phenomenon; intended to encode empirical associations such as a positive correlation between number/coverage of surface bright spots and the magnitude of PL red shift.",
                "@language": "en"
              },
              "rdfs:domain": "matsci:SuperlatticeMorphologyState",
              "rdfs:range": "matsci:PhotoluminescenceRedShift"
            },
            {
              "@id": "matsci:photonPropagationContribution",
              "rdf:type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "photon propagation contribution",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Links a photon-propagation effect (self-absorption plus re-emission) to a photoluminescence red-shift outcome, indicating that photon propagation is a contributing mechanism to the observed red shift in a sample.",
                "@language": "en"
              },
              "rdfs:domain": "matsci:PhotonPropagationEffect",
              "rdfs:range": "matsci:PhotoluminescenceRedShift"
            },
            {
              "@id": "matsci:LossOfQuantumConfinement",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Loss of quantum confinement",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "A physical transition or effect where nanocrystalline quantum confinement is reduced or lost (for example via coalescence to submicrometer crystals), leading to bulk-like optical bandgap behavior and red-shifted PL relative to confined nanocrystals.",
                "@language": "en"
              },
              "rdfs:subClassOf": "obs:PhysicalPhenomenon"
            },
            {
              "@id": "matsci:lossOfQuantumConfinementCausesRedShift",
              "rdf:type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "loss of quantum confinement causes red shift",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Relates a LossOfQuantumConfinement phenomenon to a PhotoluminescenceRedShift outcome, capturing the causal interpretation that reduced confinement (e.g. formation of larger crystallites) can produce red-shifted PL (bulk-like bandgap emission).",
                "@language": "en"
              },
              "rdfs:domain": "matsci:LossOfQuantumConfinement",
              "rdfs:range": "matsci:PhotoluminescenceRedShift"
            }
          ]
        }
      ]
    }
  }
}

